mapper.select:
SELECT e.* FROM s_employee e
JOIN s_user_account u ON u.id = e.user_id AND u.status = 'ACTIVE' AND u.deleted_at IS NULL
WHERE e.user_id = #{userId} AND e.status = 'ACTIVE'
AND e.id = #{employeeId}
AND e.venue_id = #{venueId}
ORDER BY e.id LIMIT 1

mapper.update:
UPDATE s_employee
SET user_id = #{userId}, binding_code_hash = NULL, binding_expires_at = NULL, updated_at = #{now}
WHERE id = #{employeeId} AND binding_code_hash = #{codeHash}
  AND binding_expires_at > #{now} AND status = 'ACTIVE'

UPDATE s_employee
SET user_id = NULL, binding_code_hash = NULL, binding_expires_at = NULL, updated_at = #{now}
WHERE id = #{employeeId} AND venue_id = #{venueId}
